def encrypt(s):
    d = "abcdefghijklmnopqrstuvwxyz"
    result = ""
    for char in s:
        if char.isalpha():
            index = (d.index(char.lower()) + 2) % 26
            if char.islower():
                result += d[index]
            else:
                result += d[index].upper()
        else:
            result += char
