def closest_integer(value):
    # Remove trailing zeros from the input string
    value = value.rstrip('0')

    # Check if the last two characters are ".5"
    if value.endswith('.5'):
        # Determine rounding direction based on the sign of the number
        if float(value) > 0:
            return int(float(value) + 0.5)
        else:
            return int(float(value) - 0.5)
    else:
        # Use the built-in round function for other cases
        return round(float(value))
