def is_sorted(lst):
    # Count occurrences of each integer in the list
    count = {}
    for num in lst:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    # Check if any integer appears more than twice
    for num, freq in count.items():
        if freq > 2:
            return False

    # Check if the list is sorted in ascending order
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            return False

    return True
