def fix_spaces(text):
    result = []
    start = 0
    for i, char in enumerate(text):
        if char == ' ':
            if i - start >= 3:
                result.append('-')
            elif i - start >= 2:
                result.append('_')
            start = i + 1
        else:
            result.append(char)
    return ''.join(result)

# Example usage:
